// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testFuzz_property(address caller, uint256 newMin) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 1 ether);

        bool ok;
        vm.prank(caller);
        try c.SetMinSum(newMin) { ok = true; } catch { ok = false; }

        assertTrue(ok && c.MinSum() == newMin);
    }
}
